cd . && cat > lig.py << 'EOF'
from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Chem import rdCIPLabeler

base = "[O-][C{0}](c1ccccc1)(C(F)(F)F)[C{1}H](c2ccccn2)/N=C(/C)Nc3c(C)cccc3C"
# also try other double bond config
for db in ['/N=C(/C)','/N=C(\\C)']:
    for t1 in ['@','@@']:
        for t2 in ['@','@@']:
            smi = "[O-][C{0}](c1ccccc1)(C(F)(F)F)[C{1}H](c2ccccn2)".format(t1,t2)+db+"Nc3c(C)cccc3C"
            m=Chem.MolFromSmiles(smi)
            if m is None: print('fail',smi); continue
            rdCIPLabeler.AssignCIPLabels(m)
            labs=[]
            for a in m.GetAtoms():
                if a.HasProp('_CIPCode'): labs.append((a.GetIdx(),a.GetSymbol(),a.GetProp('_CIPCode')))
            bl=[]
            for b in m.GetBonds():
                if b.GetStereo() != Chem.BondStereo.STEREONONE:
                    bl.append((b.GetBeginAtomIdx(),b.GetEndAtomIdx(),str(b.GetStereo())))
            print(db,t1,t2,labs,bl)
EOF
python3 lig.py
